head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onfilereadend]<br/>Excel 또는 CSV 파일 업로드가 완료된 후 데이터가 반영되면 발생합니다.",
    "validation" : [
        "Excel 또는 CSV 파일 업로드가 완료된 후 데이터가 반영되면 onfilereadend 이벤트가 발생해야 합니다.",
        "readCSV() 또는 advancedExcelUpload() 메소드를 통해 파일을 업로드할 수 있습니다.",
        "value 파라미터로 업로드된 파일의 확장자를 포함한 이름을 문자열로 갖습니다.",
        "Excel 파일로 다운로드한 경우엔 onfilereadend 이벤트가 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 업로드 파일은 이름/부서/금액 3개 컬럼 (헤더 1행 + 데이터 3행), 그리드 초기 데이터는 초기1/초기2 2행\n[절차] readCSV 계열 버튼은 CSV 파일(upload_sample.csv), advancedExcelUpload 계열 버튼은 Excel 파일(upload_sample.xlsx)을 선택하여 업로드\n[절차] wframe 표시가 없는 버튼은 별도 팝업창, wframe 버튼은 화면 내 레이어로 업로드 창이 열림\n[확인] 업로드 후 그리드 데이터가 파일 내용으로 바뀌는지, 결과창에 이벤트 로그와 value 값이 출력되는지 확인\n[확인] advancedExcelDownload 버튼으로 Excel 파일을 다운로드한 후에는 결과창에 이벤트 로그가 추가되지 않아야 함"', '', 'label1');

    // dataList 직접 생성 (업로드 파일과 동일한 3컬럼 구성 / 초기 2행)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="이름" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="부서" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="금액" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    strDl += '<w2:row><col1>초기1</col1><col2>초기부서1</col2><col3>10</col3></w2:row>';
    strDl += '<w2:row><col1>초기2</col1><col2>초기부서2</col2><col3>20</col3></w2:row>';
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // target 생성 (업로드 파일과 동일한 3컬럼)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" ev:onfilereadend="scwin.target1_onfilereadend" style="width:480px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="onfilereadend 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="160" inputType="text" id="column1" value="이름"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" id="column2" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="column3" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="160" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="160" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 그리드에 반영된 데이터 조회 (업로드 결과 확인용)
scwin.getGridData = function () {
    let rowCnt = target1.getRowCount();
    let arr = [];
    for (let i = 0; i < rowCnt; i++) {
        let v1 = target1.getCellData(i, "col1");
        let v2 = target1.getCellData(i, "col2");
        let v3 = target1.getCellData(i, "col3");
        arr.push('[' + (v1 == null ? '' : v1) + ',' + (v2 == null ? '' : v2) + ',' + (v3 == null ? '' : v3) + ']');
    }
    return arr.join(' ');
};



// readCSV 실행 (기본 : 별도 팝업창으로 업로드 창 오픈)
scwin.btn_readCSV_onclick = function () {
    target1.readCSV({});
};

// readCSV 실행 (wframe:true : 화면 내 레이어로 업로드 창 오픈)
scwin.btn_readCSV_wframe_onclick = function () {
    target1.readCSV({wframe : true});
};

// advancedExcelUpload 실행 (기본 : 별도 팝업창으로 업로드 창 오픈)
//  - headerExist:"1" : 파일 첫 행을 헤더로 처리 (readCSV 기본 동작과 동일하게 맞춤)
scwin.btn_advancedExcelUpload_onclick = function () {
    target1.advancedExcelUpload({headerExist : "1"});
};

// advancedExcelUpload 실행 (wframe:true : 화면 내 레이어로 업로드 창 오픈)
scwin.btn_advancedExcelUpload_wframe_onclick = function () {
    target1.advancedExcelUpload({headerExist : "1", wframe : true});
};

// advancedExcelDownload 실행 : Excel 파일로 다운로드 (@spec - onfilereadend 미발생 확인용)
scwin.btn_advancedExcelDownload_onclick = function () {
    target1.advancedExcelDownload({fileName : "onfilereadend_download.xlsx"});
    wf_body_bottom.getObj("scwin").setReturnValue("=====btn_advancedExcelDownload_onclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("Excel 파일 다운로드 실행 : 이후 onfilereadend 로그가 추가되지 않아야 함");
};



// onfilereadend : Excel 또는 CSV 파일 업로드가 완료되어 데이터가 반영된 후 발생
//  - value : 업로드된 파일의 확장자를 포함한 이름
scwin.target1_onfilereadend = function (value) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfilereadend=====");
    wf_body_bottom.getObj("scwin").setReturnValue("value : " + value);
    wf_body_bottom.getObj("scwin").setReturnValue("반영된 그리드 데이터 : " + scwin.getGridData());
}
